package com.club.controller;
import com.club.dto.*; import com.club.service.*; import jakarta.validation.Valid; import lombok.RequiredArgsConstructor; import org.springframework.http.*; import org.springframework.stereotype.Controller; import org.springframework.ui.Model; import org.springframework.web.bind.annotation.*; import org.springframework.web.servlet.mvc.support.RedirectAttributes; import java.util.List;
@RestController @RequestMapping("/api/accesos") @RequiredArgsConstructor class AccesoRestController { private final AccesoService service; @PostMapping("/entrada") @ResponseStatus(HttpStatus.CREATED) public AccesoResponse entrada(@Valid @RequestBody RegistrarAccesoDTO d){return service.registrarEntrada(d);} @PostMapping("/{id}/salida") public AccesoResponse salida(@PathVariable String id){return service.registrarSalida(id);} @GetMapping public List<AccesoResponse> listar(){return service.listar();} @GetMapping("/persona/{id}") public List<AccesoResponse> persona(@PathVariable String id){return service.listarPorPersona(id);} }
@Controller @RequestMapping("/accesos") @RequiredArgsConstructor public class AccesoController { private final AccesoService service; private final SocioService socio; @GetMapping public String listar(Model m){m.addAttribute("accesos",service.listar());m.addAttribute("personas",socio.listar());return "accesos/lista";} @PostMapping("/entrada") public String entrada(@RequestParam String personaId,RedirectAttributes ra){try{service.registrarEntrada(new RegistrarAccesoDTO(personaId));ra.addFlashAttribute("ok","Entrada registrada.");}catch(RuntimeException e){ra.addFlashAttribute("error",e.getMessage());}return "redirect:/accesos";} @PostMapping("/{id}/salida") public String salida(@PathVariable String id,RedirectAttributes ra){try{service.registrarSalida(id);ra.addFlashAttribute("ok","Salida registrada.");}catch(RuntimeException e){ra.addFlashAttribute("error",e.getMessage());}return "redirect:/accesos";} }
